import json,hashlib
from pathlib import Path
base=Path(__file__).resolve().parents[1]; old=json.loads((base/'data/external_problems.json').read_text())['problems'];by_url={p['url'].rstrip('/'):p for p in old}
rows=[]
def add(task,number,topic,description,inputs,outputs,bounds,example,answer,body,complexity,steps):
 p=dict(by_url[f'https://cses.fi/problemset/task/{number}'])
 p.update(external=False,local_task=task,family='classic',topic=topic,tags=[topic,'CSES','Correção local'],difficulty='Iniciante' if topic in ('Fundamentos','Matemática') else 'Intermediário',time_limit_sec=2.0,memory_limit_mb=256,constraints={'n_max':200000},complexity=complexity,
  statement=f'## {p["title"]}\n\n{description}\n\n### Entrada\n{inputs}\n\n### Saída\n{outputs}\n\n### Restrições\n{bounds}\n\nTempo local: 2 s por teste. Memória local: 256 MB.\n\n**Adaptação didática em português do problema CSES {number}.** Testes e implementações autorais do AutoTutor; não são os testes oficiais do CSES. O formato de entrada e saída é compatível com a tarefa de origem.',
  examples=[{'input':example,'expected_output':answer}],std_cpp='#include <bits/stdc++.h>\nusing namespace std; using ll=long long; const ll MOD=1000000007;\nint main(){ios::sync_with_stdio(false);cin.tie(nullptr);\n'+body+'\n}\n',math_essence=description,core_concepts=[topic],approach_summary=complexity,flow_steps=steps,local_pack_version=1,attribution={'title':p['title'],'url':p['url'],'statement':'Reformulação didática em português','tests':'Testes próprios gerados; sem vínculo com a avaliação oficial'})
 rows.append(p)
add('missing',1083,'Fundamentos','Uma lista contém todos os inteiros de 1 a n, exceto exatamente um. Descubra qual valor não foi fornecido.','n e, na linha seguinte, n−1 inteiros distintos.','O inteiro ausente.','2 ≤ n ≤ 200000; valores entre 1 e n.','5\n1 5 2 4\n','3\n','ll n,x;cin>>n;ll s=n*(n+1)/2;for(int i=1;i<n;i++){cin>>x;s-=x;}cout<<s<<"\\n";','O(n) tempo, O(1) memória',['Ler tamanho e números','Consolidar informação do conjunto completo','Comparar com os números recebidos','Imprimir ausente'])
add('repetitions',1069,'Fundamentos','Encontre o maior bloco consecutivo formado por uma única letra em uma sequência de DNA.','Uma string não vazia contendo apenas A, C, G e T.','O comprimento do maior bloco.','1 ≤ comprimento ≤ 1000000.','AGGGTTCCCCA\n','4\n','string s;cin>>s;int best=0,run=0;char prev=0;for(char c:s){run=c==prev?run+1:1;prev=c;best=max(best,run);}cout<<best<<"\\n";','O(n) tempo, O(n) leitura',['Ler sequência','Acompanhar bloco atual','Atualizar maior bloco','Imprimir comprimento'])
add('increasing',1094,'Guloso','Você pode aumentar qualquer elemento em uma unidade por operação. Calcule o menor total de operações para que cada elemento seja maior ou igual ao anterior.','n seguido dos n valores.','O mínimo de incrementos.','1 ≤ n ≤ 200000; 1 ≤ valores ≤ 10^9.','5\n5 2 4 4 8\n','5\n','int n;cin>>n;ll x,last=0,ans=0;while(n--){cin>>x;if(x<last)ans+=last-x;else last=x;}cout<<ans<<"\\n";','O(n) tempo, O(1) memória',['Ler sequência','Preservar limite do prefixo','Contabilizar incrementos necessários','Imprimir custo'])
add('bits',1617,'Matemática','Conte as sequências de comprimento n em que cada posição pode conter 0 ou 1. Informe a contagem módulo 1000000007.','Um inteiro n.','A contagem reduzida pelo módulo.','1 ≤ n ≤ 1000000.','4\n','16\n','ll n;cin>>n;ll b=2,r=1;while(n){if(n&1)r=r*b%MOD;b=b*b%MOD;n>>=1;}cout<<r<<"\\n";','O(log n) tempo, O(1) memória',['Ler comprimento','Combinar escolhas independentes','Reduzir pelo módulo','Imprimir contagem'])
add('zeros',1618,'Matemática','Quantos algarismos zero aparecem consecutivamente no fim da representação decimal de n fatorial? Não imprima o fatorial.','Um inteiro n.','A quantidade de zeros finais.','1 ≤ n ≤ 10^9.','26\n','6\n','ll n;cin>>n;ll ans=0;for(ll p=5;p<=n;p*=5)ans+=n/p;cout<<ans<<"\\n";','O(log n) tempo, O(1) memória',['Ler n','Contar fatores relevantes','Incluir potências repetidas','Imprimir zeros'])
add('piles',1754,'Matemática','Em cada movimento, retire uma moeda de uma pilha e duas da outra. Para cada par de pilhas, decida se ambas podem ficar vazias sem quantidades negativas.','t, seguido de t linhas com a e b.','YES ou NO para cada par.','1 ≤ t ≤ 100000; 0 ≤ a,b ≤ 10^9.','4\n0 0\n1 2\n2 2\n3 6\n','YES\nYES\nNO\nYES\n','int t;cin>>t;while(t--){ll a,b;cin>>a>>b;cout<<(((a+b)%3==0&&max(a,b)<=2*min(a,b))?"YES":"NO")<<"\\n";}','O(t) tempo, O(1) memória',['Ler pares','Verificar conservação das retiradas','Verificar viabilidade das pilhas','Responder cada caso'])
add('distinct',1621,'Estruturas de Dados','Determine quantos valores diferentes existem em uma lista. Repetições do mesmo valor contam uma única vez.','n seguido de n inteiros.','A quantidade de valores distintos.','1 ≤ n ≤ 200000; 1 ≤ valores ≤ 10^9.','6\n8 2 8 4 2 9\n','4\n','int n;cin>>n;set<ll>s;while(n--){ll x;cin>>x;s.insert(x);}cout<<s.size()<<"\\n";','O(n log n) tempo, O(n) memória',['Ler valores','Agrupar valores iguais','Contar grupos distintos','Imprimir quantidade'])
add('maxsub',1643,'DP','Escolha um segmento contíguo e não vazio da sequência cuja soma seja a maior possível. Valores negativos também fazem parte da entrada.','n seguido de n inteiros.','A maior soma de um segmento não vazio.','1 ≤ n ≤ 200000; −10^9 ≤ valores ≤ 10^9.','6\n-4 3 -1 5 -8 2\n','7\n','int n;cin>>n;ll x,cur=0,best=LLONG_MIN;for(int i=0;i<n;i++){cin>>x;cur=i?max(x,cur+x):x;best=max(best,cur);}cout<<best<<"\\n";','O(n) tempo, O(1) memória',['Ler sequência','Melhor segmento terminado na posição','Atualizar melhor resposta global','Imprimir soma'])
add('sticks',1074,'Guloso','Ajuste todos os comprimentos para um mesmo valor inteiro. Aumentar ou diminuir uma unidade custa uma unidade. Minimize o custo total.','n e n comprimentos.','O custo mínimo.','1 ≤ n ≤ 200000; 1 ≤ comprimentos ≤ 10^9.','4\n1 3 7 9\n','12\n','int n;cin>>n;vector<ll>a(n);for(auto&x:a)cin>>x;sort(a.begin(),a.end());ll ans=0;for(ll x:a)ans+=abs(x-a[n/2]);cout<<ans<<"\\n";','O(n log n) tempo, O(n) memória',['Ler comprimentos','Ordenar posições','Avaliar equilíbrio do custo','Imprimir mínimo'])
add('missingcoin',2183,'Guloso','Cada moeda pode ser usada no máximo uma vez. Descubra o menor inteiro positivo que não pode ser obtido somando um subconjunto das moedas.','n e n valores de moedas.','A menor soma positiva impossível.','1 ≤ n ≤ 200000; 1 ≤ valores ≤ 10^9.','4\n1 2 2 8\n','6\n','int n;cin>>n;vector<ll>a(n);for(auto&x:a)cin>>x;sort(a.begin(),a.end());ll reach=1;for(ll x:a){if(x>reach)break;reach+=x;}cout<<reach<<"\\n";','O(n log n) tempo, O(n) memória',['Ordenar moedas','Preservar faixa de somas coberta','Encontrar primeira lacuna','Imprimir soma impossível'])
add('ferris',1090,'Guloso','Distribua as crianças em cabines com capacidade para até duas pessoas. A soma dos pesos em cada cabine não pode ultrapassar x. Minimize a quantidade de cabines.','n e x; depois n pesos.','O menor número de cabines.','1 ≤ n ≤ 200000; 1 ≤ peso ≤ x ≤ 10^9.','5 10\n2 8 5 3 7\n','3\n','int n;ll x;cin>>n>>x;vector<ll>a(n);for(auto&v:a)cin>>v;sort(a.begin(),a.end());int l=0,r=n-1,ans=0;while(l<=r){if(l<r&&a[l]+a[r]<=x)l++;r--;ans++;}cout<<ans<<"\\n";','O(n log n) tempo, O(n) memória',['Ordenar pesos','Comparar extremos disponíveis','Reservar cabine e avançar','Imprimir quantidade'])
add('movies',1629,'Guloso','Selecione o maior número de filmes que uma pessoa consegue assistir integralmente. É permitido iniciar um filme exatamente quando o anterior termina.','n, seguido de n pares início fim.','O máximo de filmes compatíveis.','1 ≤ n ≤ 200000; 1 ≤ início < fim ≤ 10^9.','4\n1 4\n2 3\n3 5\n5 8\n','3\n','int n;cin>>n;vector<pair<ll,ll>>a(n);for(auto&[r,l]:a)cin>>l>>r;sort(a.begin(),a.end());ll last=0;int ans=0;for(auto[r,l]:a)if(l>=last){ans++;last=r;}cout<<ans<<"\\n";','O(n log n) tempo, O(n) memória',['Ordenar por término','Verificar compatibilidade','Atualizar agenda','Imprimir quantidade'])
add('apartments',1084,'Guloso','Cada candidato deseja um tamanho de apartamento e aceita uma diferença absoluta de até k. Cada apartamento e cada candidato podem participar de no máximo uma atribuição. Maximize as atribuições.','n m k; n tamanhos desejados; m tamanhos disponíveis.','O máximo de candidatos atendidos.','1 ≤ n,m ≤ 200000; 0 ≤ k ≤ 10^9; 1 ≤ tamanhos ≤ 10^9.','3 4 1\n10 20 30\n9 19 40 31\n','3\n','int n,m;ll k;cin>>n>>m>>k;vector<ll>a(n),b(m);for(auto&x:a)cin>>x;for(auto&x:b)cin>>x;sort(a.begin(),a.end());sort(b.begin(),b.end());int i=0,j=0,ans=0;while(i<n&&j<m){if(abs(a[i]-b[j])<=k){ans++;i++;j++;}else if(b[j]<a[i]-k)j++;else i++;}cout<<ans<<"\\n";','O(n log n + m log m) tempo, O(n+m) memória',['Ordenar desejos e ofertas','Comparar menor par disponível','Descartar incompatíveis ou combinar','Imprimir atendidos'])
add('dice',1633,'DP','Conte as sequências ordenadas de valores entre 1 e 6 cuja soma seja n. Sequências com ordens diferentes contam separadamente. Use módulo 1000000007.','Um inteiro n.','A contagem módulo 1000000007.','1 ≤ n ≤ 1000000.','4\n','8\n','int n;cin>>n;vector<ll>d(n+1);d[0]=1;for(int i=1;i<=n;i++)for(int k=1;k<=6&&k<=i;k++)d[i]=(d[i]+d[i-k])%MOD;cout<<d[n]<<"\\n";','O(n) tempo, O(n) memória',['Definir estado pela soma','Considerar último lançamento','Combinar predecessores','Imprimir contagem'])
for task,num,description,output,body,answer in [
 ('mincoins',1634,'Determine a menor quantidade de moedas necessária para totalizar x. Há quantidade ilimitada de cada valor. Se for impossível, responda −1.','O mínimo de moedas ou −1.','vector<int>d(x+1,x+1);d[0]=0;for(int s=1;s<=x;s++)for(int v:c)if(v<=s)d[s]=min(d[s],d[s-v]+1);cout<<(d[x]>x?-1:d[x]);','2\n'),
 ('coins1',1635,'Conte as sequências de moedas cuja soma é x. A ordem importa e cada valor pode ser reutilizado. Use módulo 1000000007.','A contagem de sequências módulo 1000000007.','vector<ll>d(x+1);d[0]=1;for(int s=1;s<=x;s++)for(int v:c)if(v<=s)d[s]=(d[s]+d[s-v])%MOD;cout<<d[x];','5\n'),
 ('coins2',1636,'Conte as combinações de moedas cuja soma é x. A ordem não importa e cada valor pode ser reutilizado. Use módulo 1000000007.','A contagem de combinações módulo 1000000007.','vector<ll>d(x+1);d[0]=1;for(int v:c)for(int s=v;s<=x;s++)d[s]=(d[s]+d[s-v])%MOD;cout<<d[x];','3\n')]:
 add(task,num,'DP',description,'n x, seguidos de n valores distintos de moedas.',output,'1 ≤ n ≤ 100; 1 ≤ x ≤ 1000000; 1 ≤ moedas ≤ 1000000.','2 4\n1 2\n',answer,'int n,x;cin>>n>>x;vector<int>c(n);for(auto&v:c)cin>>v;'+body+'cout<<"\\n";','O(n x) tempo, O(x) memória',['Definir estados de soma','Distinguir ordem e disponibilidade','Atualizar transições','Imprimir estado do alvo'])
add('digits',1637,'DP','Partindo de n, a cada passo subtraia um dos algarismos não nulos do valor atual. Minimize o número de passos até zero.','Um inteiro n.','O mínimo de subtrações.','1 ≤ n ≤ 1000000.','21\n','4\n','int n;cin>>n;vector<int>d(n+1,n+1);d[0]=0;for(int i=1;i<=n;i++)for(int v=i;v;v/=10)if(v%10)d[i]=min(d[i],d[i-v%10]+1);cout<<d[n]<<"\\n";','O(n log n) tempo, O(n) memória',['Definir estado pelo valor','Enumerar algarismos disponíveis','Minimizar transições','Imprimir distância até zero'])
add('grid',1638,'DP','Conte os caminhos do canto superior esquerdo ao inferior direito de uma grade quadrada. Só são permitidos passos para a direita ou para baixo, sem atravessar células bloqueadas (*). Use módulo 1000000007.','n, seguido de n linhas com n caracteres . ou *.','A quantidade de caminhos módulo 1000000007.','1 ≤ n ≤ 1000.','3\n...\n.*.\n...\n','2\n','int n;cin>>n;vector<ll>d(n);d[0]=1;for(int i=0;i<n;i++){string s;cin>>s;for(int j=0;j<n;j++){if(s[j]==\'*\')d[j]=0;else if(j)d[j]=(d[j]+d[j-1])%MOD;}}cout<<d[n-1]<<"\\n";','O(n²) tempo, O(n) memória',['Ler grade','Zerar estados bloqueados','Combinar chegada de cima e esquerda','Imprimir destino'])
add('books',1158,'DP','Cada livro tem preço e quantidade de páginas. Escolha livros com preço total de até x para maximizar as páginas. Cada livro pode ser comprado no máximo uma vez.','n x; n preços; n quantidades de páginas.','O máximo de páginas possível.','1 ≤ n ≤ 1000; 1 ≤ x ≤ 100000; 1 ≤ preços,páginas ≤ 1000.','3 7\n3 4 6\n5 7 10\n','12\n','int n,x;cin>>n>>x;vector<int>p(n),v(n),d(x+1);for(auto&a:p)cin>>a;for(auto&a:v)cin>>a;for(int i=0;i<n;i++)for(int j=x;j>=p[i];j--)d[j]=max(d[j],d[j-p[i]]+v[i]);cout<<d[x]<<"\\n";','O(n x) tempo, O(x) memória',['Ler preço e benefício','Processar cada livro uma vez','Preservar camada anterior','Imprimir melhor benefício'])
add('rooms',1192,'Grafos','Células de piso (.) ligadas por lados pertencem ao mesmo cômodo. Paredes (#) não podem ser atravessadas. Conte os componentes de piso; diagonais não conectam células.','n m e n linhas com m caracteres . ou #.','A quantidade de cômodos.','1 ≤ n,m ≤ 1000.','3 4\n..#.\n####\n.#..\n','4\n','int n,m;cin>>n>>m;vector<string>g(n);for(auto&s:g)cin>>s;int ans=0;int dr[]={1,-1,0,0},dc[]={0,0,1,-1};for(int i=0;i<n;i++)for(int j=0;j<m;j++)if(g[i][j]==\'.\'){ans++;vector<pair<int,int>>q{{i,j}};g[i][j]=\'#\';while(!q.empty()){auto[r,c]=q.back();q.pop_back();for(int k=0;k<4;k++){int a=r+dr[k],b=c+dc[k];if(a>=0&&a<n&&b>=0&&b<m&&g[a][b]==\'.\'){g[a][b]=\'#\';q.push_back({a,b});}}}}cout<<ans<<"\\n";','O(n m) tempo e memória',['Ler mapa','Encontrar piso não visitado','Percorrer componente sem recursão profunda','Contar componentes'])
add('subsum',1661,'Prefix Sum','Conte os segmentos contíguos e não vazios cuja soma é exatamente x. Os valores podem ser positivos, negativos ou zero.','n x, seguidos dos n valores.','O número de segmentos de soma x.','1 ≤ n ≤ 200000; −10^9 ≤ x,valores ≤ 10^9.','4 0\n1 -1 0 2\n','3\n','int n;ll x;cin>>n>>x;map<ll,ll>f;f[0]=1;ll s=0,ans=0;while(n--){ll a;cin>>a;s+=a;ans+=f[s-x];f[s]++;}cout<<ans<<"\\n";','O(n log n) tempo, O(n) memória',['Ler alvo','Manter frequências de prefixos','Consultar prefixos compatíveis antes de inserir','Imprimir contagem'])
for task,num,topic,description,output,body,answer,comp in [
 ('xor',1650,'Prefix Sum','Responda ao XOR bit a bit de todos os valores em cada intervalo fechado [l,r]. A sequência não muda.','O XOR de cada consulta, uma resposta por linha.','vector<ll>p(n+1);for(int i=1;i<=n;i++)p[i]=p[i-1]^a[i-1];while(q--){int l,r;cin>>l>>r;cout<<(p[r]^p[l-1])<<"\\n";}','4\n3\n','O(n+q) tempo, O(n) memória'),
 ('rmq',1647,'Estruturas de Dados','Responda ao menor valor em cada intervalo fechado [l,r] de uma sequência que não sofre alterações.','O mínimo de cada consulta, uma resposta por linha.','int sz=1;while(sz<n)sz*=2;vector<ll>t(2*sz,LLONG_MAX);for(int i=0;i<n;i++)t[sz+i]=a[i];for(int i=sz-1;i;i--)t[i]=min(t[2*i],t[2*i+1]);while(q--){int l,r;cin>>l>>r;l+=sz-1;r+=sz-1;ll res=LLONG_MAX;while(l<=r){if(l&1)res=min(res,t[l++]);if(!(r&1))res=min(res,t[r--]);l/=2;r/=2;}cout<<res<<"\\n";}','1\n3\n','O(n+q log n) tempo, O(n) memória')]:
 add(task,num,topic,description,'n q; n valores; q linhas l r.',output,'1 ≤ n,q ≤ 200000; 1 ≤ valores ≤ 10^9; 1 ≤ l ≤ r ≤ n.','4 2\n1 3 2 4\n1 4\n2 2\n',answer,'int n,q;cin>>n>>q;vector<ll>a(n);for(auto&v:a)cin>>v;'+body,comp,['Ler sequência fixa','Preparar estrutura de consulta','Responder intervalos inclusivos','Imprimir respostas'])
